def OnGuessPDF(self, event):
    viewer = util.getWindowsPDFViewer()

    if viewer:
        self.progEntry.SetValue(viewer)
    else:
        wx.MessageBox("Unable to guess. Please set the path manually.",
                      "PDF Viewer", wx.OK, cfgFrame)

    # Attempt to find the default PDF viewer on Linux
    try:
        import subprocess
        viewer = subprocess.check_output(['xdg-settings', 'get', 'default-web-browser']).strip().decode('utf-8')
        self.progEntry.SetValue(viewer)
    except Exception:
